import injuryRegionMap from './injuryRegionMap.json';

/**
 * Per-triangle injury region for every mesh of the horse model, generated by
 * `frontend/scripts/build-injury-regions.mjs`.
 *
 * Regions come from the dominant skin bone of each triangle, so a click resolves by triangle
 * index instead of a point normalized against the runtime scene box (which included mane/strand
 * translations and shifted every region). Entries are keyed by triangle count, which is unique
 * per mesh in this model and stable across node renames.
 */
type MeshRegionMap = { mesh: string; triangles: number; region: string };

const MESHES = injuryRegionMap.meshes as MeshRegionMap[];
const CODES = injuryRegionMap.codes as Record<string, string>;

function findMesh(triangleCount: number | undefined): MeshRegionMap | null {
  if (triangleCount == null) return null;
  return MESHES.find((entry) => entry.triangles === triangleCount) ?? null;
}

/** Region key for a hit triangle, or null when the mesh does not match the generated map. */
export function regionKeyForFaceIndex(
  faceIndex: number | undefined | null,
  triangleCount: number | undefined,
): string | null {
  if (faceIndex == null || faceIndex < 0) return null;
  const mesh = findMesh(triangleCount);
  if (!mesh || faceIndex >= mesh.region.length) return null;
  return CODES[mesh.region[faceIndex]] ?? null;
}
